import{_ as e,c as a,aU as l,a as r}from"./chunks/framework.DIXiA2XH.js";const n="/assets/%E8%BD%AF%E8%80%8303.BmAwTEhK.png",o="/assets/%E8%BD%AF%E8%80%8304.BZ0-IN_g.png",s="/assets/%E8%BD%AF%E8%80%8306.Dnqk3dL4.png",i="/assets/%E8%BD%AF%E8%80%8301.6O-EAaYo.png",d="/assets/%E8%BD%AF%E8%80%8310.DGm4Q43w.png",h="/assets/%E8%BD%AF%E8%80%8305.BGDHVwjs.jpg",k=JSON.parse('{"title":"软考","description":"","frontmatter":{},"headers":[],"relativePath":"note/stationmaster/soft-exam/index.md","filePath":"note/stationmaster/soft-exam/index.md","lastUpdated":1773326622000}'),p={name:"note/stationmaster/soft-exam/index.md"};function c(f,t,g,m,x,b){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="软考" tabindex="-1">软考 <a class="header-anchor" href="#软考" aria-label="Permalink to &quot;软考&quot;">​</a></h1><blockquote><p>一个月速通高级系统架构设计师 : <a href="https://zhuanlan.zhihu.com/p/679349315" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/679349315</a></p><p>系统架构设计师历年真题含答案与解析历年真题 : <a href="https://ebook.qicoder.com/%E7%B3%BB%E7%BB%9F%E6%9E%B6%E6%9E%84%E8%AE%BE%E8%AE%A1%E5%B8%88/" target="_blank" rel="noreferrer">https://ebook.qicoder.com/系统架构设计师/</a></p></blockquote><p>软考达人 ： <a href="https://www.ruankaodaren.com/" target="_blank" rel="noreferrer">https://www.ruankaodaren.com/</a></p><p><a href="https://wwd.lanzout.com/imJWx34cnckf" target="_blank" rel="noreferrer">https://wwd.lanzout.com/imJWx34cnckf</a> <br><a href="https://wwd.lanzout.com/iXDPX34cne9g" target="_blank" rel="noreferrer">https://wwd.lanzout.com/iXDPX34cne9g</a> <br><a href="https://wwd.lanzout.com/i7iuL34cn89a" target="_blank" rel="noreferrer">https://wwd.lanzout.com/i7iuL34cn89a</a></p><h2 id="什么是软考" tabindex="-1">什么是软考 <a class="header-anchor" href="#什么是软考" aria-label="Permalink to &quot;什么是软考&quot;">​</a></h2><p>计算机技术与软件专业技术资格水平考试</p><h2 id="报考分类" tabindex="-1">报考分类 <a class="header-anchor" href="#报考分类" aria-label="Permalink to &quot;报考分类&quot;">​</a></h2><p><a href="https://www.ruankao.org.cn/article/content/2504271432042066942471973.html" target="_blank" rel="noreferrer">https://www.ruankao.org.cn/article/content/2504271432042066942471973.html</a></p><p><img src="'+n+'" alt=""><img src="'+o+'" alt=""><img src="'+s+'" alt=""></p><h2 id="报考条件" tabindex="-1">报考条件 <a class="header-anchor" href="#报考条件" aria-label="Permalink to &quot;报考条件&quot;">​</a></h2><ul><li>不限专业</li><li>不限年龄</li><li>不限学历</li><li>无需逐级报考</li></ul><h2 id="考试形式" tabindex="-1">考试形式 <a class="header-anchor" href="#考试形式" aria-label="Permalink to &quot;考试形式&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>合格标准：每个科目需要都超过45分</p><h2 id="如何报考" tabindex="-1">如何报考 <a class="header-anchor" href="#如何报考" aria-label="Permalink to &quot;如何报考&quot;">​</a></h2><p>官网：<a href="https://www.ruankao.org.cn/index.html" target="_blank" rel="noreferrer">https://www.ruankao.org.cn/index.html</a></p><h3 id="报名时间" tabindex="-1">报名时间 <a class="header-anchor" href="#报名时间" aria-label="Permalink to &quot;报名时间&quot;">​</a></h3><p>上半年：多数省份集中在 2025年3月中旬至4月初（如广东：3月24日-4月1日填报，3月24日-4月2日缴费）2610。</p><p>下半年：一般在 2025年8月中旬至9月初（如广东：8月18日-26日填报，8月18日-27日缴费）</p><h3 id="报名流程" tabindex="-1">报名流程 <a class="header-anchor" href="#报名流程" aria-label="Permalink to &quot;报名流程&quot;">​</a></h3><p>实名认证：下载“国家网络身份认证APP”，完成人脸识别。</p><p>官网报名：</p><p>登录全国统一报名平台：<a href="https://bm.ruankao.org.cn/sign/welcome" target="_blank" rel="noreferrer">https://bm.ruankao.org.cn/sign/welcome</a></p><p>填报信息：选择考区、上传白底证件照（需用官方工具处理），填写学历/工作信息。</p><p>缴费确认：审核通过后24小时内完成缴费，逾期视为放弃</p><p><img src="'+d+'" alt=""></p><h3 id="报名费用标准" tabindex="-1">报名费用标准 <a class="header-anchor" href="#报名费用标准" aria-label="Permalink to &quot;报名费用标准&quot;">​</a></h3><p>费用由各省自主制定，主要分两类模式：</p><div class="tip custom-block github-alert"><p class="custom-block-title">总结：初级/中级总费用约 100-160元，高级约 180-300元，特殊科目（如信息处理技术员）可能更高</p><p></p></div><ol><li>按级别收费（主流）</li></ol><table tabindex="0"><thead><tr><th style="text-align:left;">地区</th><th style="text-align:left;">初级</th><th style="text-align:left;">中级</th><th style="text-align:left;">高级</th><th style="text-align:left;">备注</th></tr></thead><tbody><tr><td style="text-align:left;">广东</td><td style="text-align:left;">73元/科</td><td style="text-align:left;">73元/科</td><td style="text-align:left;">73元/科</td><td style="text-align:left;">机考科目统一单价</td></tr><tr><td style="text-align:left;">湖南</td><td style="text-align:left;">130元</td><td style="text-align:left;">160元</td><td style="text-align:left;">190元</td><td style="text-align:left;">级别统一定价</td></tr><tr><td style="text-align:left;">青海</td><td style="text-align:left;">140元</td><td style="text-align:left;">140元</td><td style="text-align:left;">210元</td><td style="text-align:left;">高级含3科</td></tr></tbody></table><ol start="2"><li>按科目收费</li></ol><table tabindex="0"><thead><tr><th style="text-align:left;">地区</th><th style="text-align:left;">单价</th><th style="text-align:left;">高级总费用</th><th style="text-align:left;">备注</th></tr></thead><tbody><tr><td style="text-align:left;">北京</td><td style="text-align:left;">57元/科</td><td style="text-align:left;">171元（3科）</td><td style="text-align:left;">信息处理技术员170元</td></tr><tr><td style="text-align:left;">重庆</td><td style="text-align:left;">75元/科</td><td style="text-align:left;">225元（3科）</td><td style="text-align:left;">中级2科150元</td></tr><tr><td style="text-align:left;">上海</td><td style="text-align:left;">70元（含10元报名费）</td><td style="text-align:left;">70元/科</td><td style="text-align:left;">每科固定费用</td></tr></tbody></table><h2 id="杭州的e类人才-软考-需要中级还是高级" tabindex="-1">杭州的E类人才 软考 需要中级还是高级？ <a class="header-anchor" href="#杭州的e类人才-软考-需要中级还是高级" aria-label="Permalink to &quot;杭州的E类人才 软考 需要中级还是高级？&quot;">​</a></h2><p>杭州E类人才认定，通常需要的是软考高级证书，而不是中级。软考高级证书对应的是副高级职称，而E类人才的认定标准中，副高级职称是其中一个重要条件，并且通常还需要相关的专业技术成果作为辅助。</p><p>也就是说 <strong>杭州E类人才认定</strong> 需要 ：软考（高级证书）+ 成果（软著/专利/论文，三选一）</p><p><img src="'+h+'" alt=""></p><h2 id="网友软考分享" tabindex="-1">网友软考分享 <a class="header-anchor" href="#网友软考分享" aria-label="Permalink to &quot;网友软考分享&quot;">​</a></h2><p><a href="https://blog.beanbang.cn/2025/01/06/2024-ruankao-architect/" target="_blank" rel="noreferrer">https://blog.beanbang.cn/2025/01/06/2024-ruankao-architect/</a></p>',39)])])}const y=e(p,[["render",c]]);export{k as __pageData,y as default};
